(function(root){
'use strict';
class PCWebAudioOutput {
 constructor(){this.ctx=null;this.gain=null;this.sources=new Set();this.enabled=false;this.nextStart=0;this.dropped=0;}
 get pendingSeconds(){return this.enabled&&this.ctx?Math.max(0,this.nextStart-this.ctx.currentTime):0;}
 async enable(){
  const C=root.AudioContext||root.webkitAudioContext;
  if(!C)throw new Error('WebAudio není v tomto prohlížeči dostupné');
  if(!this.ctx){this.ctx=new C();this.gain=this.ctx.createGain();this.gain.gain.value=0.12;this.gain.connect(this.ctx.destination);}
  await this.ctx.resume();this.enabled=true;this.nextStart=this.ctx.currentTime;
 }
 enqueue(pcm){
  if(!this.enabled||!this.ctx||!pcm?.length)return;
  if(this.nextStart<this.ctx.currentTime)this.nextStart=this.ctx.currentTime;
  // Never accumulate unlimited latency while the guest outruns real time.
  // The guest may run faster than wall time. cpuFrame applies backpressure
  // instead of throwing away entire notes. Keep a hard emergency cap.
  if(this.pendingSeconds>3){this.dropped++;return;}
  const buf=this.ctx.createBuffer(1,pcm.length,22050);
  buf.copyToChannel(pcm,0);
  const src=this.ctx.createBufferSource();src.buffer=buf;src.connect(this.gain);
  src.onended=()=>{this.sources.delete(src);src.disconnect();};
  this.sources.add(src);src.start(this.nextStart);this.nextStart+=buf.duration;
 }
 flush(){for(const src of this.sources){try{src.stop();src.disconnect();}catch(_){}}this.sources.clear();if(this.ctx)this.nextStart=this.ctx.currentTime;}
 disable(){this.enabled=false;this.flush();if(this.ctx)this.ctx.suspend().catch(()=>{});}
}
root.MDPC_AUDIO_OUTPUT={PCWebAudioOutput};
})(typeof window!=='undefined'?window:globalThis);
